import{z as s,x as E,o as r,c as h,q as i,j as l,D as e,d as n,s as o,S as p}from"./chunks/framework.C8m1ZpeB.js";const B=JSON.parse('{"title":"RLHF 流程","description":"","frontmatter":{"title":"RLHF 流程","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlhf-pipeline.md","filePath":"llm/rlhf-pipeline.md","lastUpdated":1791063341000}'),A={name:"llm/rlhf-pipeline.md"};function m(P,a,_,d,R,c){const t=E("Mermaid");return r(),h("div",null,[a[2]||(a[2]=i('<h1 id="rlhf-流程" tabindex="-1">RLHF 流程 <a class="header-anchor" href="#rlhf-流程" aria-label="Permalink to &quot;RLHF 流程&quot;">​</a></h1><div class="epigraph"><p>先用示范把模型拉进可接受的语言区域，再从人类偏好学一个奖励，最后用强化学习在奖励上升的同时用 KL 拴住参考策略。</p><footer>—— Ouyang et al., Training language models to follow instructions with human feedback, NeurIPS 2022；偏好学习接到 Christiano et al., NeurIPS 2017</footer></div><p><a href="/llm/deployment-monitoring">上一课</a>把「对齐概念与监控」课序收在部署后监控：上线之后抽样、分流、修复或再评测的闭环，补发版评测盖不住的分布缺口。本课打开强化学习课程。Christiano 等人把「难以写进标量函数的目标」收成人类两两比较，再学奖励、用 RL 优化策略。Ouyang 等人把这套偏好 RL 接到指令微调后的语言模型上，构成后来被广泛称作 RLHF 的三阶段流水线：监督微调（SFT）、奖励模型（RM）、近端策略优化（PPO）。它不是单一损失，而是三条数据与四个模型角色的工序：策略、参考、奖励、价值。后续的 <a href="/llm/grpo">GRPO</a>、<a href="/llm/rloo">RLOO</a>、直接偏好方法，都是在改第三段怎么走，很少取消「先有示范与偏好」这一事实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练语言模型会补全互联网，不会自动「按用户意图、在安全边界内」作答。只做 SFT，模型模仿标注员写过的回答，覆盖有限，也学不会在多个合理回答之间按人类偏好排序。只做偏好分类，又没有把分类器接到生成策略上的优化器。Christiano 的设定是：人类无法逐步打分机器人的每个关节，但能比较两段行为谁更好；Ouyang 的设定是：标注员可以写示范、也可以对同一提示的两个模型回答打序，但无法为每个 token 写奖励。</p><p><span class="marginnote">SFT 与 RLHF 的分工可以类比学开车：SFT 是看教练示范并照着开，教练没演示过的路况你就不会；RLHF 是教练不再给标准动作，只对你的每种开法说「这样更好」或「那样更差」。前者覆盖有限但起步稳，后者能泛化到没见过的情形，但需要先会开（SFT 打底）教练的评价才有意义。</span></p><p>要把偏好变成可生成的行为，必须把比较数据收成对完整作答的标量，再在 token 级策略上做强化学习。中间会经过一个显式奖励模型——这是经典 RLHF 与后来「跳过 RM、直接吃偏好对」的分界。本篇只写带 RM 的流程。</p><h3 id="三个数据面不能混成一张表" tabindex="-1">三个数据面不能混成一张表 <a class="header-anchor" href="#三个数据面不能混成一张表" aria-label="Permalink to &quot;三个数据面不能混成一张表&quot;">​</a></h3><p>示范数据：提示加一条人类（或教师）回答，供 SFT。比较数据：同一提示下两条回答加序关系，供 RM。RL 提示：只有 \\(x\\)，回答由当前策略采样，供 PPO。把比较里的胜方再当 SFT，是 <a href="/llm/rejection-sampling-rft">拒绝采样</a>，不是第三阶段。把示范直接当奖励 1、其余当 0，会毁掉 RM 的成对信息。流水线首先是数据协议，其次才是 PPO 公式。</p><p><span class="marginnote">InstructGPT 论文里的人类数据分标注员写的示范与标注员给的比较，来源与协议不同。不要写成「RLHF 只用点赞点踩」。比较是相对的，绝对分数标定是额外的工程，原文并不依赖用户界面上的五星。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段一：在示范上做因果 LM，得到 \\(\\pi_{\\mathrm{SFT}}\\)。它既是聊天模型的起点，也是后面 KL 的参考锚 \\(\\pi_{\\mathrm{ref}}\\)（实现上常把参考冻结为 SFT）。阶段二：对成对数据 \\((x,y_w,y_l)\\) 训奖励模型，典型为 Bradley-Terry：</p> \\[p(y_w \\succ y_l\\mid x)=\\sigma\\bigl(r_\\phi(x,y_w)-r_\\phi(x,y_l)\\bigr) \\]<p>\\(r_\\phi\\) 通常是在 SFT 初始化的标量头，对完整序列打分。阶段三：策略 \\(\\pi_\\theta\\) 从 \\(\\pi_{\\mathrm{SFT}}\\) 出发，对 RL 提示采样 \\(y\\)，用 \\(r_\\phi\\) 打分，减去对参考的 KL，再以 PPO 更新；同时训一个价值函数估优势。详见 <a href="/llm/ppo-llm">PPO 实现</a> 与 <a href="/llm/ppo-kl-value">KL 与价值</a>。</p>',14)),(r(),l(p,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20SFT%5B%22SFT%20%E7%A4%BA%E8%8C%83%22%5D%0A%20%20SFT%20--%3E%20REF%5B%22%E5%86%BB%E7%BB%93%E5%8F%82%E8%80%83%20%CF%80_ref%22%5D%0A%20%20SFT%20--%3E%20RM%5B%22%E5%A5%96%E5%8A%B1%E6%A8%A1%E5%9E%8B%20r_%CF%86%22%5D%0A%20%20SFT%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%20%CF%80_%CE%B8%22%5D%0A%20%20RM%20--%3E%20PPO%5B%22PPO%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20REF%20--%3E%20PPO%0A%20%20POL%20--%3E%20ROL%5B%22%E9%87%87%E6%A0%B7%20y%22%5D%0A%20%20ROL%20--%3E%20PPO%0A%20%20PPO%20--%3E%20POL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="第四个角色-价值函数" tabindex="-1">第四个角色：价值函数 <a class="header-anchor" href="#第四个角色-价值函数" aria-label="Permalink to &quot;第四个角色：价值函数&quot;">​</a></h3><p>PPO 是 actor-critic：策略之外还要 \\(V_\\psi\\)，在每个 token 上估计期望回报，用来构造优势、降低方差。它与 RM 不是同一个头：RM 给序列奖励（再拆成逐步），\\(V\\) 拟合「从当前前缀往后还能拿多少」。两者初始化都可以来自 SFT，但优化目标不同，崩溃模式也不同，见 <a href="/llm/ac-stability">Actor-Critic 稳定性</a>。工程上这是 RLHF 相对 SFT 最重的一块：多一份与策略同规模的 critic 常驻反向。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SFT 把策略的支持集拉到「像助手的语言」，否则随机预训练模型的采样对标注员不可比，RM 学的是乱码上的偏好，没有意义。RM 把离散的比较变成可微的标量场；策略沿这个场上升时，会找到 RM 的漏洞（奖励黑客）——所以要用 \\(\\mathrm{KL}(\\pi_\\theta\\|\\pi_{\\mathrm{ref}})\\) 把策略钉在 SFT 邻域。KL 不是审美，是承认 RM 只在参考分布附近被校准。</p>',4)),(r(),l(p,null,{default:e(()=>[o(t,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22RL%20%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20S%5B%22%E7%AD%96%E7%95%A5%20%CF%80_%CE%B8%20%E9%87%87%E6%A0%B7%E5%AE%8C%E6%95%B4%E5%9B%9E%E7%AD%94%20y%22%5D%0A%20%20S%20--%3E%20R%5B%22RM%20%E7%BB%99%E6%95%B4%E6%9D%A1%20y%20%E6%89%93%E4%B8%80%E4%B8%AA%E5%88%86%20r%22%5D%0A%20%20R%20--%3E%20K%5B%22%E6%AF%8F%E4%B8%AA%20token%20%E5%87%8F%20KL(%CF%80_%CE%B8%E2%80%96%CF%80_ref)%20%E6%83%A9%E7%BD%9A%22%5D%0A%20%20K%20--%3E%20V%5B%22critic%20%E6%8A%8A%E7%A8%80%E7%96%8F%E5%A5%96%E5%8A%B1%E6%8B%86%E6%88%90%E6%AF%8F%E6%AD%A5%E4%BC%98%E5%8A%BF%22%5D%0A%20%20V%20--%3E%20U%5B%22PPO%20%E9%99%90%E5%88%B6%E6%AD%A5%E9%95%BF%E6%9B%B4%E6%96%B0%20%CF%80_%CE%B8%22%5D%0A%20%20U%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p>PPO 的近端约束限制每步策略更新幅度，避免一次更新跑出 RM 的可信区。采样必须来自当前 \\(\\pi_\\theta\\)（或近端旧策略再重要性加权），因此第三阶段是在线生成，和 <a href="/llm/online-offline-distill">离线蒸馏</a> 的冻数据不同。奖励通常在序列结束才由 RM 给出，中间 token 的稠密信号主要来自逐步 KL 项；稀疏终点奖励正是 critic 存在的理由。</p><p><span class="marginnote">KL 惩罚可以想成橡皮筋：\\(\\beta\\) 是松紧，策略每偏离参考一步就多扣一点分。数字代入：RM 给整条回答 +5 分，若 \\(\\beta=0.2\\)、整段累计偏离相当于 15，净奖励只剩 \\(5-0.2\\times15=2\\)；回答走得越远，扣得越多——这就是「拴住策略、防止跑进 RM 不靠谱的区域」的具体算术。</span></p><p><span class="marginnote">Ouyang 等人强调：RLHF 优化的是标注员（及后来的用户）偏好的代理，不是「真」对齐。代理在比较协议、标注员池、提示集上都会偏。换一群标注员，RM 与策略都要重做，不是改一个 β 能修。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="第三阶段最贵-也最先被替换" tabindex="-1">第三阶段最贵，也最先被替换 <a class="header-anchor" href="#第三阶段最贵-也最先被替换" aria-label="Permalink to &quot;第三阶段最贵，也最先被替换&quot;">​</a></h3><p>PPO 需要策略、参考、RM、critic 四份前向，生成长、占 KV，超参多。许多后续工作保留 SFT+偏好，改掉 PPO：拒绝采样微调只用 RM 选胜方再 SFT；GRPO / RLOO 去掉 critic；直接偏好优化跳过显式 RM。这些是对第三段的替换，不是宣布前两段作废。没有比较数据时，可验证奖励（数学对错）可以代替 RM，那是 R1 一类流水线，仍有「参考 + 策略梯度」，只是奖励改成规则。</p><p><span class="marginnote">初学者容易把奖励曲线上升当成「模型变好了」。实际上策略可能只是学会了讨好 RM：写得冗长、说话谄媚、把安全词挂在嘴边。奖励只是人类偏好的代理分数，产品上必须另比指令遵循与安全回归——只盯奖励曲线做实验，等于只看后视镜开车。</span></p><p>RM 过强会让策略学会讨好打分头：冗长、谄媚、表面安全。KL 过强则策略不敢离开 SFT，RL 段等于没跑。β、裁剪范围、生成温度、批内提示多样性都要一起扫，孤立报「PPO 无效」没有信息。产品上应把 SFT 检查点当回归锚：RL 之后既要比 RM 分，也要比指令遵循与安全回归，不能只看奖励曲线。</p><p><span class="marginnote">Christiano 2017 的主体是模拟控制与 Atari 一类轨迹，比较的是片段行为；Ouyang 2022 比较的是完整自然语言作答。迁移过来的是「偏好 → 奖励 → RL」的骨架，不是控制里的动作频率或折扣公式原样照搬。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经典 RLHF 是 SFT → 成对偏好训 RM → PPO，参考策略拴 KL。</li><li>示范、比较、RL 提示是三种数据，不能混用协议。</li><li>价值函数是 PPO 的 critic，与 RM 分工不同，也是后续无 critic 方法想砍掉的成本。</li><li>RM 只在参考邻域可信，故 KL 与近端更新是流程的一部分，不是可选装饰。</li><li>出处：Christiano et al., NeurIPS 2017；Ouyang et al., NeurIPS 2022。PPO 算法见 Schulman et al., 2017。</li></ul>',11))])}const T=s(A,[["render",m]]);export{B as __pageData,T as default};
